THOUGHT: Now I understand that `CircleType` is defined as the string "circle". 

Based on my analysis, the issues in the `ExtractCircle` function are:

1. It doesn't track whether a radius was found
2. It always returns `true` at the end instead of checking if both coordinates and radius were found
3. It should validate that both pieces of information exist before returning success

Let me fix these issues:

```bash
sed -i '355,400d' ./geo/parse.go && cat <<'EOF' >> ./geo/parse.go
func ExtractCircle(thing interface{}) (*geojson.GeoShape, bool) {
	thingVal := reflect.ValueOf(thing)
	if !thingVal.IsValid() {
		return nil, false
	}

	rv := &geojson.GeoShape{
		Type:   CircleType,
		Center: make([]float64, 0, 2),
	}

	var foundRadius, foundCoordinates bool

	if thingVal.Kind() == reflect.Map {
		iter := thingVal.MapRange()
		for iter.Next() {

			if iter.Key().String() == "radius" {
				rv.Radius = iter.Value().Interface().(string)
				foundRadius = true
				continue
			}

			if iter.Key().String() == "coordinates" {
				lng, lat, found := ExtractGeoPoint(iter.Value().Interface())
				if !found {
					return nil, false
				}
				rv.Center = append(rv.Center, lng, lat)
				foundCoordinates = true
			}
		}
	}

	return rv, foundRadius && foundCoordinates
}

// ExtractGeoShapeCoordinates takes an interface{} and tries it's best to
// interpret the coordinates for any of the given geoshape typ like
// a point, multipoint, linestring, multilinestring, polygon, multipolygon,
EOF
```

