	circleMapMissingCoords := map[string]interface{}{
		"radius": "1km",
	}

	_, found = ExtractCircle(circleMapMissingCoords)
	if found {
		t.Errorf("Expected not to find circle when coordinates are missing")
	}
}
EOF
```

